<?php require 'includes/functions.php';require_login();$q=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$q->execute([(int)($_GET['id']??0),user()['id']]);$o=$q->fetch();if(!$o)go('orders.php');$i=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$i->execute([$o['id']]);$items=$i->fetchAll();$pageTitle='Order Details';require 'includes/header.php';require 'includes/navbar.php'; ?><main class="container my-5"><div class="d-flex justify-content-between"><div><h1 class="section-title"><?=e($o['order_number'])?></h1><p><?=date('d M Y, h:i A',strtotime($o['created_at']))?></p></div><div><a class="btn btn-outline-dark" href="<?=base('track-order.php?id='.$o['id'])?>">Track order</a><a class="btn btn-dark" href="<?=base('invoice.php?id='.$o['id'])?>">Invoice</a></div></div><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Product</th><th>Size</th><th>Qty</th><th>Price</th></tr></thead><tbody><?php foreach($items as $x): ?><tr><td><?=e($x['product_name'])?></td><td><?=e($x['size'])?></td><td><?=$x['quantity']?></td><td><?=money($x['unit_price']*$x['quantity'])?></td></tr><?php endforeach ?></tbody></table></div><div class="row mt-4"><div class="col-md-6"><h5>Shipping address</h5><p><?=nl2br(e($o['shipping_address']))?></p></div><div class="col-md-6"><h5>Total</h5><p class="fs-4 fw-bold"><?=money($o['total_amount'])?></p><span class="badge text-bg-dark"><?=e(str_replace('_',' ',$o['order_status']))?></span></div></div></main><?php require 'includes/footer.php'; ?>
